const items = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0); // Normalizar a medianoche

// Palabras clave para detectar empleo, ferias o procesos de selección
const keywordsEmpleo = [
  "emprego", "vaga", "vagas", "oportunidade", "oportunidades", 
  "processo seletivo", "contratando", "trabalho", "curriculum", 
  "currículo", "feira", "mutirão", "entrevista", 
  "balcão do trabalhador", "agência do trabalhador"
];

let feriasProximas = [];

for (const item of items) {
  // Capturamos el texto de la publicación
  const textoPost = (item.json.caption || item.json.text || item.json.description || "").toLowerCase();

  // Verificamos si el texto menciona algo relacionado a empleo o ferias
  const esDeEmpleo = keywordsEmpleo.some(keyword => textoPost.includes(keyword));

  if (esDeEmpleo) {
    // Buscamos la fecha en los campos típicos que devuelve Apify para Instagram
    const rawDate = item.json.timestamp || item.json.date || item.json.pubDate || item.json.createdAt; 
    const nombreFeria = item.json.caption ? item.json.caption.substring(0, 60) + "..." : "Oportunidad de Empleo";
    const enlaceFeria = item.json.url || item.json.link || "";

    if (rawDate) {
      const feriaDate = new Date(rawDate);

      // Validar si la fecha es válida y si es futura o de hoy
      if (!isNaN(feriaDate.getTime()) && feriaDate >= today) {
        feriasProximas.push({
          nombre: nombreFeria,
          fecha: feriaDate,
          fechaStr: feriaDate.toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric' }),
          url: enlaceFeria
        });
      }
    }
  }
}

// Ordenar por fecha más cercana
feriasProximas.sort((a, b) => a.fecha - b.fecha);

// Si no hay ferias o vacantes próximas que coincidan
if (feriasProximas.length === 0) {
  return [{ json: { mensajeAlerta: "= Monitoreo activo: Se revisaron las publicaciones recientes de Cascavel y ACIC, pero aún no hay convocatorias de empleo nuevas." } }];
}

// Construir un mensaje unificado y limpio
let mensaje = "=¨ *¡Nuevas Ferias / Vacantes de Empleo Detectadas!* =¨\n\n";
feriasProximas.forEach((f, index) => {
  mensaje += `*${index + 1}. ${f.nombre}*\n`;
  mensaje += `=Å Fecha: ${f.fechaStr}\n`;
  if (f.url) mensaje += `= Más info: ${f.url}\n`;
  mensaje += `-------------------\n`;
});

return [{ json: { mensajeAlerta: mensaje } }];

